package main

import (
	"os"
	"runtime/pprof"
)

var sink float64

//go:noinline
func parse(n int) {
	for i := 0; i < n; i++ {
		sink += float64(i%7) * 1.5
	}
}

//go:noinline
func encode(n int) {
	for i := 0; i < n*6; i++ {
		sink += float64(i%11) * 2.5
	}
}

//go:noinline
func handle(n int) {
	parse(n)
	encode(n)
}

func main() {
	f, _ := os.Create("cpu.pb.gz")
	pprof.StartCPUProfile(f)
	for i := 0; i < 300; i++ {
		handle(1_000_000)
	}
	pprof.StopCPUProfile()
	f.Close()
}
